package br.ufpa.dsai.estilomarcado.autenticacao.security;

import java.io.IOException;
import java.time.Duration;
import java.time.Instant;

import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.web.filter.OncePerRequestFilter;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import jakarta.servlet.http.HttpSession;

public class SessaoAbsolutaFilter extends OncePerRequestFilter {

    public static final String AUTENTICADO_EM = "AUTENTICADO_EM";
    private static final Duration DURACAO_MAXIMA = Duration.ofHours(12);

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain filterChain)
            throws ServletException, IOException {
        HttpSession sessao = request.getSession(false);
        if (sessao != null && sessao.getAttribute(AUTENTICADO_EM) instanceof Instant inicio
                && inicio.plus(DURACAO_MAXIMA).isBefore(Instant.now())) {
            sessao.invalidate();
            SecurityContextHolder.clearContext();
        }
        filterChain.doFilter(request, response);
    }
}

package br.ufpa.dsai.estilomarcado.autenticacao.security;

import java.io.Serial;
import java.io.Serializable;
import java.util.Collection;
import java.util.List;

import org.springframework.security.core.GrantedAuthority;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.core.userdetails.UserDetails;

import br.ufpa.dsai.estilomarcado.autenticacao.model.PerfilUsuario;
import br.ufpa.dsai.estilomarcado.autenticacao.model.Usuario;

public record UsuarioPrincipal(
        Long id,
        String nome,
        String email,
        PerfilUsuario perfil,
        Long unidadeId,
        Long profissionalId) implements UserDetails, Serializable {

    @Serial
    private static final long serialVersionUID = 1L;

    public static UsuarioPrincipal from(Usuario usuario) {
        return new UsuarioPrincipal(
                usuario.getId(),
                usuario.getNome(),
                usuario.getEmailNormalizado(),
                usuario.getPerfil(),
                usuario.getUnidade() == null ? null : usuario.getUnidade().getId(),
                usuario.getProfissional() == null ? null : usuario.getProfissional().getId());
    }

    @Override
    public Collection<? extends GrantedAuthority> getAuthorities() {
        return List.of(new SimpleGrantedAuthority("ROLE_" + perfil.name()));
    }

    @Override
    public String getPassword() {
        return "";
    }

    @Override
    public String getUsername() {
        return email;
    }
}

package br.ufpa.dsai.estilomarcado.autenticacao.service;

import java.util.Map;

import org.springframework.session.FindByIndexNameSessionRepository;
import org.springframework.session.Session;
import org.springframework.stereotype.Service;

@Service
public class SessaoService {

    private final FindByIndexNameSessionRepository<? extends Session> repository;

    public SessaoService(FindByIndexNameSessionRepository<? extends Session> repository) {
        this.repository = repository;
    }

    public void invalidarTodas(String emailNormalizado) {
        Map<String, ? extends Session> sessoes = repository.findByPrincipalName(emailNormalizado);
        sessoes.keySet().forEach(repository::deleteById);
    }
}

