import { HttpClient, HttpErrorResponse, HttpInterceptorFn } from '@angular/common/http';
import { computed, inject, Injectable, signal } from '@angular/core';
import { catchError, map, Observable, of, switchMap, tap } from 'rxjs';

export type Perfil = 'CLIENTE' | 'PROFISSIONAL' | 'RECEPCAO' | 'ADMINISTRADOR';
export type Estado = 'PENDENTE' | 'ATIVA' | 'BLOQUEADA' | 'DESATIVADA';

export interface Sessao {
  id: number;
  nome: string;
  email: string;
  perfil: Perfil;
  unidadeId: number | null;
  profissionalId: number | null;
}

export interface Usuario extends Sessao {
  estado: Estado;
}

export interface ErroApi {
  mensagem?: string;
  campos?: Record<string, string>;
}

export const credentialsInterceptor: HttpInterceptorFn = (request, next) =>
  next(request.clone({ withCredentials: true }));

@Injectable({ providedIn: 'root' })
export class AuthService {
  private readonly http = inject(HttpClient);
  readonly sessao = signal<Sessao | null | undefined>(undefined);
  readonly autenticado = computed(() => this.sessao() !== null && this.sessao() !== undefined);
  readonly administrador = computed(() => this.sessao()?.perfil === 'ADMINISTRADOR');

  carregarSessao(): Observable<Sessao | null> {
    return this.http.get<Sessao>('/api/autenticacao/sessao').pipe(
      tap((sessao) => this.sessao.set(sessao)),
      map((sessao) => sessao as Sessao | null),
      catchError(() => {
        this.sessao.set(null);
        return of(null);
      })
    );
  }

  cadastrar(dados: { nome: string; email: string; senha: string; confirmacaoSenha: string }): Observable<unknown> {
    return this.mutacao(() => this.http.post('/api/autenticacao/cadastros', dados));
  }

  ativar(token: string): Observable<unknown> {
    return this.mutacao(() => this.http.post('/api/autenticacao/ativacoes', { token }));
  }

  login(email: string, senha: string): Observable<Sessao> {
    return this.mutacao(() => this.http.post<Sessao>('/api/autenticacao/sessoes', { email, senha })).pipe(
      tap((sessao) => this.sessao.set(sessao))
    );
  }

  logout(): Observable<unknown> {
    return this.mutacao(() => this.http.delete('/api/autenticacao/sessao')).pipe(
      tap(() => this.sessao.set(null))
    );
  }

  solicitarRecuperacao(email: string): Observable<unknown> {
    return this.mutacao(() => this.http.post('/api/autenticacao/recuperacoes', { email }));
  }

  redefinir(token: string, senha: string, confirmacaoSenha: string): Observable<unknown> {
    return this.mutacao(() =>
      this.http.post('/api/autenticacao/redefinicoes', { token, senha, confirmacaoSenha })
    );
  }

  aceitarConvite(token: string, senha: string, confirmacaoSenha: string): Observable<unknown> {
    return this.mutacao(() =>
      this.http.post('/api/autenticacao/convites', { token, senha, confirmacaoSenha })
    );
  }

  meuPerfil(): Observable<Usuario> {
    return this.http.get<Usuario>('/api/usuarios/me');
  }

  atualizarNome(nome: string): Observable<Usuario> {
    return this.mutacao(() => this.http.patch<Usuario>('/api/usuarios/me', { nome }));
  }

  listarUsuarios(unidadeId: number): Observable<Usuario[]> {
    return this.http.get<Usuario[]>(`/api/unidades/${unidadeId}/usuarios-internos`);
  }

  criarUsuario(unidadeId: number, dados: {
    nome: string;
    email: string;
    perfil: Perfil;
    profissionalId: number | null;
  }): Observable<Usuario> {
    return this.mutacao(() =>
      this.http.post<Usuario>(`/api/unidades/${unidadeId}/usuarios-internos`, dados)
    );
  }

  static mensagemErro(error: unknown): string {
    if (error instanceof HttpErrorResponse) {
      const body = error.error as ErroApi | undefined;
      return body?.mensagem ?? 'Nao foi possivel concluir a operacao.';
    }
    return 'Nao foi possivel concluir a operacao.';
  }

  private mutacao<T>(acao: () => Observable<T>): Observable<T> {
    return this.http.get('/api/autenticacao/csrf').pipe(switchMap(() => acao()));
  }
}
package br.ufpa.dsai.estilomarcado.autenticacao.security;

import java.util.Arrays;
import java.util.List;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.HttpMethod;
import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.core.userdetails.UserDetailsService;
import org.springframework.security.core.userdetails.UsernameNotFoundException;
import org.springframework.security.web.AuthenticationEntryPoint;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.access.AccessDeniedHandler;
import org.springframework.security.web.access.intercept.AuthorizationFilter;
import org.springframework.security.web.context.HttpSessionSecurityContextRepository;
import org.springframework.security.web.context.SecurityContextRepository;
import org.springframework.security.web.csrf.CookieCsrfTokenRepository;
import org.springframework.session.web.http.CookieSerializer;
import org.springframework.session.web.http.DefaultCookieSerializer;
import org.springframework.web.cors.CorsConfiguration;
import org.springframework.web.cors.CorsConfigurationSource;
import org.springframework.web.cors.UrlBasedCorsConfigurationSource;

import tools.jackson.databind.ObjectMapper;

@Configuration
@EnableMethodSecurity
public class SegurancaConfig {

    @Bean
    PasswordEncoder passwordEncoder(@Value("${app.auth.password-cost:12}") int custo) {
        return new BCryptPasswordEncoder(custo);
    }

    @Bean
    UserDetailsService userDetailsService() {
        return username -> { throw new UsernameNotFoundException("autenticacao por formulario desabilitada"); };
    }

    @Bean
    CookieSerializer cookieSerializer(@Value("${SESSION_COOKIE_SECURE:false}") boolean seguro) {
        DefaultCookieSerializer serializer = new DefaultCookieSerializer();
        serializer.setCookieName("SESSION");
        serializer.setCookiePath("/");
        serializer.setUseHttpOnlyCookie(true);
        serializer.setUseSecureCookie(seguro);
        serializer.setSameSite("Lax");
        return serializer;
    }

    @Bean
    SecurityContextRepository securityContextRepository() {
        return new HttpSessionSecurityContextRepository();
    }

    @Bean
    SecurityFilterChain securityFilterChain(HttpSecurity http,
                                            SecurityContextRepository contextRepository,
                                            ObjectMapper objectMapper) throws Exception {
        CookieCsrfTokenRepository csrfRepository = CookieCsrfTokenRepository.withHttpOnlyFalse();
        csrfRepository.setCookiePath("/");

        AuthenticationEntryPoint entrada = (request, response, ex) ->
                RespostaSeguranca.escrever(objectMapper, response, 401, "autenticacao necessaria");
        AccessDeniedHandler negado = (request, response, ex) ->
                RespostaSeguranca.escrever(objectMapper, response, 403, "acesso negado");

        http
                .csrf(csrf -> csrf.csrfTokenRepository(csrfRepository))
                .cors(cors -> { })
                .securityContext(context -> context
                        .securityContextRepository(contextRepository)
                        .requireExplicitSave(true))
                .sessionManagement(session -> session
                        .sessionCreationPolicy(SessionCreationPolicy.IF_REQUIRED)
                        .sessionFixation(fixation -> fixation.changeSessionId()))
                .exceptionHandling(exceptions -> exceptions
                        .authenticationEntryPoint(entrada)
                        .accessDeniedHandler(negado))
                .authorizeHttpRequests(authorize -> authorize
                        .requestMatchers("/actuator/health", "/actuator/info").permitAll()
                        .requestMatchers(HttpMethod.GET, "/api/autenticacao/sessao").authenticated()
                        .requestMatchers("/api/autenticacao/**").permitAll()
                        .requestMatchers(HttpMethod.GET,
                                "/api/unidades/*/servicos", "/api/servicos/*").permitAll()
                        .requestMatchers("/api/unidades/*/usuarios-internos/**").hasRole("ADMINISTRADOR")
                        .requestMatchers(HttpMethod.POST, "/api/unidades/*/servicos").hasRole("ADMINISTRADOR")
                        .requestMatchers(HttpMethod.PUT, "/api/servicos/*").hasRole("ADMINISTRADOR")
                        .requestMatchers(HttpMethod.PATCH, "/api/servicos/**").hasRole("ADMINISTRADOR")
                        .anyRequest().authenticated())
                .logout(logout -> logout.disable())
                .httpBasic(basic -> basic.disable())
                .formLogin(form -> form.disable())
                .addFilterBefore(new SessaoAbsolutaFilter(), AuthorizationFilter.class);

        return http.build();
    }

    @Bean
    CorsConfigurationSource corsConfigurationSource(
            @Value("${app.auth.allowed-origins:http://localhost:4200}") String origens) {
        CorsConfiguration config = new CorsConfiguration();
        config.setAllowedOrigins(Arrays.stream(origens.split(",")).map(String::trim).toList());
        config.setAllowedMethods(List.of("GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"));
        config.setAllowedHeaders(List.of("Content-Type", "X-XSRF-TOKEN"));
        config.setAllowCredentials(true);
        config.setMaxAge(3600L);
        UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();
        source.registerCorsConfiguration("/**", config);
        return source;
    }
}
package br.ufpa.dsai.estilomarcado.autenticacao.api;

import java.time.Instant;
import java.util.Map;

import org.springframework.http.HttpStatus;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContext;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.web.context.SecurityContextRepository;
import org.springframework.security.web.csrf.CsrfToken;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

import br.ufpa.dsai.estilomarcado.autenticacao.api.dto.CadastroRequest;
import br.ufpa.dsai.estilomarcado.autenticacao.api.dto.EmailRequest;
import br.ufpa.dsai.estilomarcado.autenticacao.api.dto.LoginRequest;
import br.ufpa.dsai.estilomarcado.autenticacao.api.dto.MensagemResponse;
import br.ufpa.dsai.estilomarcado.autenticacao.api.dto.NovaSenhaRequest;
import br.ufpa.dsai.estilomarcado.autenticacao.api.dto.SessaoResponse;
import br.ufpa.dsai.estilomarcado.autenticacao.api.dto.TokenRequest;
import br.ufpa.dsai.estilomarcado.autenticacao.exception.CredenciaisInvalidasException;
import br.ufpa.dsai.estilomarcado.autenticacao.security.SessaoAbsolutaFilter;
import br.ufpa.dsai.estilomarcado.autenticacao.security.UsuarioAtual;
import br.ufpa.dsai.estilomarcado.autenticacao.security.UsuarioPrincipal;
import br.ufpa.dsai.estilomarcado.autenticacao.service.AutenticacaoService;
import br.ufpa.dsai.estilomarcado.autenticacao.service.LimiteRequisicoesService;
import br.ufpa.dsai.estilomarcado.autenticacao.service.NormalizadorEmail;
import br.ufpa.dsai.estilomarcado.autenticacao.service.AuditoriaService;
import jakarta.servlet.http.Cookie;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import jakarta.servlet.http.HttpSession;
import jakarta.validation.Valid;

@RestController
@RequestMapping("/api/autenticacao")
public class AutenticacaoController {

    private static final String MENSAGEM_CADASTRO =
            "Se o e-mail estiver disponivel, enviaremos as instrucoes de ativacao.";
    private static final String MENSAGEM_RECUPERACAO =
            "Se existir uma conta apta para este e-mail, enviaremos as instrucoes de recuperacao.";

    private final AutenticacaoService service;
    private final LimiteRequisicoesService limiteService;
    private final SecurityContextRepository contextRepository;
    private final UsuarioAtual usuarioAtual;
    private final AuditoriaService auditoria;

    public AutenticacaoController(AutenticacaoService service,
                                  LimiteRequisicoesService limiteService,
                                  SecurityContextRepository contextRepository,
                                  UsuarioAtual usuarioAtual,
                                  AuditoriaService auditoria) {
        this.service = service;
        this.limiteService = limiteService;
        this.contextRepository = contextRepository;
        this.usuarioAtual = usuarioAtual;
        this.auditoria = auditoria;
    }

    @GetMapping("/csrf")
    public Map<String, String> csrf(CsrfToken token) {
        return Map.of("headerName", token.getHeaderName(), "token", token.getToken());
    }

    @PostMapping("/cadastros")
    @ResponseStatus(HttpStatus.ACCEPTED)
    public MensagemResponse cadastrar(@Valid @RequestBody CadastroRequest request,
                                      HttpServletRequest servletRequest) {
        String origem = origem(servletRequest);
        limiteService.verificarEnvio("cadastro", origem, NormalizadorEmail.normalizar(request.email()));
        service.cadastrarCliente(request, origem);
        return new MensagemResponse(MENSAGEM_CADASTRO);
    }

    @PostMapping("/ativacoes")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    public void ativar(@Valid @RequestBody TokenRequest request, HttpServletRequest servletRequest) {
        service.ativar(request.token(), origem(servletRequest));
    }

    @PostMapping("/ativacoes/reenviar")
    @ResponseStatus(HttpStatus.ACCEPTED)
    public MensagemResponse reenviar(@Valid @RequestBody EmailRequest request,
                                     HttpServletRequest servletRequest) {
        String origem = origem(servletRequest);
        limiteService.verificarEnvio("ativacao", origem, NormalizadorEmail.normalizar(request.email()));
        service.reenviarAtivacao(request.email(), origem);
        return new MensagemResponse(MENSAGEM_CADASTRO);
    }

    @PostMapping("/sessoes")
    public SessaoResponse login(@Valid @RequestBody LoginRequest request,
                                HttpServletRequest servletRequest,
                                HttpServletResponse servletResponse) {
        String origem = origem(servletRequest);
        limiteService.verificarLogin(origem);
        var resultado = service.autenticar(request.email(), request.senha(), origem);
        if (!resultado.sucesso()) {
            throw new CredenciaisInvalidasException();
        }

        UsuarioPrincipal principal = resultado.principal();
        var autenticacao = UsernamePasswordAuthenticationToken.authenticated(
                principal, null, principal.getAuthorities());
        SecurityContext contexto = SecurityContextHolder.createEmptyContext();
        contexto.setAuthentication(autenticacao);
        SecurityContextHolder.setContext(contexto);

        HttpSession sessao = servletRequest.getSession(false);
        if (sessao == null) {
            sessao = servletRequest.getSession(true);
        } else {
            servletRequest.changeSessionId();
        }
        sessao.setMaxInactiveInterval(30 * 60);
        sessao.setAttribute(SessaoAbsolutaFilter.AUTENTICADO_EM, Instant.now());
        contextRepository.saveContext(contexto, servletRequest, servletResponse);
        return SessaoResponse.from(principal);
    }

    @GetMapping("/sessao")
    public SessaoResponse sessao() {
        return SessaoResponse.from(usuarioAtual.get());
    }

    @DeleteMapping("/sessao")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    public void logout(HttpServletRequest request, HttpServletResponse response) {
        var authentication = SecurityContextHolder.getContext().getAuthentication();
        if (authentication != null && authentication.getPrincipal() instanceof UsuarioPrincipal principal) {
            auditoria.registrar(principal.id(), "LOGOUT", true, origem(request), null);
        }
        HttpSession sessao = request.getSession(false);
        if (sessao != null) {
            sessao.invalidate();
        }
        SecurityContextHolder.clearContext();
        Cookie cookie = new Cookie("SESSION", "");
        cookie.setHttpOnly(true);
        cookie.setPath("/");
        cookie.setMaxAge(0);
        response.addCookie(cookie);
    }

    @PostMapping("/recuperacoes")
    @ResponseStatus(HttpStatus.ACCEPTED)
    public MensagemResponse recuperar(@Valid @RequestBody EmailRequest request,
                                      HttpServletRequest servletRequest) {
        String origem = origem(servletRequest);
        limiteService.verificarEnvio("recuperacao", origem, NormalizadorEmail.normalizar(request.email()));
        service.solicitarRecuperacao(request.email(), origem);
        return new MensagemResponse(MENSAGEM_RECUPERACAO);
    }

    @PostMapping("/redefinicoes")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    public void redefinir(@Valid @RequestBody NovaSenhaRequest request, HttpServletRequest servletRequest) {
        service.redefinirSenha(request, origem(servletRequest));
    }

    @PostMapping("/convites")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    public void aceitarConvite(@Valid @RequestBody NovaSenhaRequest request, HttpServletRequest servletRequest) {
        service.aceitarConvite(request, origem(servletRequest));
    }

    private String origem(HttpServletRequest request) {
        return request.getRemoteAddr();
    }
}
