package br.ufpa.dsai.estilomarcado.catalogo.api.exception;

import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.Map;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import br.ufpa.dsai.estilomarcado.autenticacao.exception.CredenciaisInvalidasException;
import br.ufpa.dsai.estilomarcado.autenticacao.exception.LimiteTentativasException;
import br.ufpa.dsai.estilomarcado.autenticacao.exception.TokenInvalidoException;

/**
 * Traduz excecoes do catalogo de servicos em respostas HTTP consistentes.
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(CredenciaisInvalidasException.class)
    public ResponseEntity<ErroResponse> handleCredenciais(CredenciaisInvalidasException ex) {
        return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                .body(new ErroResponse(HttpStatus.UNAUTHORIZED.value(), ex.getMessage()));
    }

    @ExceptionHandler(TokenInvalidoException.class)
    public ResponseEntity<ErroResponse> handleToken(TokenInvalidoException ex) {
        return ResponseEntity.unprocessableEntity()
                .body(new ErroResponse(HttpStatus.UNPROCESSABLE_ENTITY.value(), ex.getMessage()));
    }

    @ExceptionHandler(LimiteTentativasException.class)
    public ResponseEntity<ErroResponse> handleLimite(LimiteTentativasException ex) {
        return ResponseEntity.status(HttpStatus.TOO_MANY_REQUESTS)
                .body(new ErroResponse(HttpStatus.TOO_MANY_REQUESTS.value(), ex.getMessage()));
    }

    @ExceptionHandler(AccessDeniedException.class)
    public ResponseEntity<ErroResponse> handleAcessoNegado(AccessDeniedException ex) {
        return ResponseEntity.status(HttpStatus.FORBIDDEN)
                .body(new ErroResponse(HttpStatus.FORBIDDEN.value(), "acesso negado"));
    }

    @ExceptionHandler(HttpMessageNotReadableException.class)
    public ResponseEntity<ErroResponse> handleJsonInvalido(HttpMessageNotReadableException ex) {
        return ResponseEntity.badRequest()
                .body(new ErroResponse(HttpStatus.BAD_REQUEST.value(), "requisicao invalida"));
    }

    @ExceptionHandler(RecursoNaoEncontradoException.class)
    public ResponseEntity<ErroResponse> handleNaoEncontrado(RecursoNaoEncontradoException ex) {
        return ResponseEntity.status(HttpStatus.NOT_FOUND)
                .body(new ErroResponse(HttpStatus.NOT_FOUND.value(), ex.getMessage()));
    }

    @ExceptionHandler(ConflitoException.class)
    public ResponseEntity<ErroResponse> handleConflito(ConflitoException ex) {
        return ResponseEntity.status(HttpStatus.CONFLICT)
                .body(new ErroResponse(HttpStatus.CONFLICT.value(), ex.getMessage()));
    }

    @ExceptionHandler(RegraDeNegocioException.class)
    public ResponseEntity<ErroResponse> handleRegraDeNegocio(RegraDeNegocioException ex) {
        return ResponseEntity.status(HttpStatus.UNPROCESSABLE_ENTITY)
                .body(new ErroResponse(HttpStatus.UNPROCESSABLE_ENTITY.value(), ex.getMessage()));
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<ErroResponse> handleValidacao(MethodArgumentNotValidException ex) {
        Map<String, String> campos = new LinkedHashMap<>();
        ex.getBindingResult().getFieldErrors()
                .forEach(erro -> campos.putIfAbsent(erro.getField(), erro.getDefaultMessage()));

        ErroResponse resposta = new ErroResponse(HttpStatus.BAD_REQUEST.value(),
                "requisicao invalida", campos);
        return ResponseEntity.badRequest().body(resposta);
    }

    public record ErroResponse(int status, String mensagem, Map<String, String> campos, Instant timestamp) {
        public ErroResponse(int status, String mensagem) {
            this(status, mensagem, Map.of(), Instant.now());
        }

        public ErroResponse(int status, String mensagem, Map<String, String> campos) {
            this(status, mensagem, campos, Instant.now());
        }
    }
}
package br.ufpa.dsai.estilomarcado.autenticacao.service;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import br.ufpa.dsai.estilomarcado.autenticacao.model.EventoSeguranca;
import br.ufpa.dsai.estilomarcado.autenticacao.repository.EventoSegurancaRepository;

@Service
public class AuditoriaService {

    private final EventoSegurancaRepository repository;

    public AuditoriaService(EventoSegurancaRepository repository) {
        this.repository = repository;
    }

    @Transactional
    public void registrar(Long usuarioId, String tipo, boolean sucesso, String origem, String detalhes) {
        repository.save(new EventoSeguranca(
                usuarioId,
                tipo,
                sucesso ? "SUCESSO" : "FALHA",
                limitar(origem, 100),
                limitar(detalhes, 500)));
    }

    private String limitar(String valor, int tamanho) {
        if (valor == null || valor.length() <= tamanho) {
            return valor;
        }
        return valor.substring(0, tamanho);
    }
}
package br.ufpa.dsai.estilomarcado.autenticacao.service;

import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.mail.SimpleMailMessage;
import org.springframework.mail.javamail.JavaMailSender;
import org.springframework.stereotype.Component;

@Component
public class EmailAutenticacaoSmtp implements EmailAutenticacaoGateway {

    private final JavaMailSender mailSender;
    private final String frontendUrl;

    public EmailAutenticacaoSmtp(JavaMailSender mailSender,
                                 @Value("${app.frontend-url}") String frontendUrl) {
        this.mailSender = mailSender;
        this.frontendUrl = frontendUrl.replaceAll("/$", "");
    }

    @Override
    public void enviarAtivacao(String destinatario, String nome, String token) {
        enviar(destinatario, "Ative sua conta no Estilo Marcado",
                "Ola, " + nome + "!\n\nAtive sua conta neste link (valido por 24 horas):\n"
                        + link("/ativar", token));
    }

    @Override
    public void enviarConvite(String destinatario, String nome, String token) {
        enviar(destinatario, "Convite para o Estilo Marcado",
                "Ola, " + nome + "!\n\nConclua seu convite e defina sua senha neste link (valido por 24 horas):\n"
                        + link("/convite", token));
    }

    @Override
    public void enviarRecuperacao(String destinatario, String nome, String token) {
        enviar(destinatario, "Recuperacao de conta do Estilo Marcado",
                "Ola, " + nome + "!\n\nRedefina sua senha neste link (valido por 30 minutos):\n"
                        + link("/redefinir-senha", token));
    }

    @Override
    public void enviarSenhaAlterada(String destinatario, String nome) {
        enviar(destinatario, "Sua senha foi alterada",
                "Ola, " + nome + "!\n\nA senha da sua conta no Estilo Marcado foi alterada."
                        + " Se voce nao reconhece esta acao, solicite uma nova recuperacao imediatamente.");
    }

    private String link(String caminho, String token) {
        return frontendUrl + caminho + "?token=" + URLEncoder.encode(token, StandardCharsets.UTF_8);
    }

    private void enviar(String destinatario, String assunto, String texto) {
        SimpleMailMessage mensagem = new SimpleMailMessage();
        mensagem.setFrom("nao-responda@estilomarcado.local");
        mensagem.setTo(destinatario);
        mensagem.setSubject(assunto);
        mensagem.setText(texto);
        mailSender.send(mensagem);
    }
}

