name: estilo-marcado

services:
  postgres:
    image: postgres:17-alpine
    container_name: estilo-marcado-postgres
    environment:
      POSTGRES_DB: ${POSTGRES_DB}
      POSTGRES_USER: ${POSTGRES_USER}
      POSTGRES_PASSWORD: ${POSTGRES_PASSWORD}
    ports:
      - "${POSTGRES_PORT}:5432"
    volumes:
      - postgres_data:/var/lib/postgresql/data
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -U $$POSTGRES_USER -d $$POSTGRES_DB"]
      interval: 5s
      timeout: 5s
      retries: 12
      start_period: 10s
    networks:
      - estilo_marcado_network

  backend:
    build:
      context: ./src/backend
      dockerfile: Dockerfile.dev
    container_name: estilo-marcado-backend
    environment:
      SPRING_PROFILES_ACTIVE: docker
      SPRING_DATASOURCE_URL: jdbc:postgresql://postgres:5432/${POSTGRES_DB}
      SPRING_DATASOURCE_USERNAME: ${POSTGRES_USER}
      SPRING_DATASOURCE_PASSWORD: ${POSTGRES_PASSWORD}
      MAIL_HOST: mailpit
      MAIL_PORT: 1025
      FRONTEND_URL: ${FRONTEND_URL:-http://localhost:4200}
      AUTH_ALLOWED_ORIGINS: ${AUTH_ALLOWED_ORIGINS:-http://localhost:4200}
      AUTH_PASSWORD_COST: ${AUTH_PASSWORD_COST:-12}
      SESSION_COOKIE_SECURE: ${SESSION_COOKIE_SECURE:-false}
      AUTH_BOOTSTRAP_ADMIN_ENABLED: ${AUTH_BOOTSTRAP_ADMIN_ENABLED:-false}
      AUTH_BOOTSTRAP_ADMIN_NAME: ${AUTH_BOOTSTRAP_ADMIN_NAME:-Administrador}
      AUTH_BOOTSTRAP_ADMIN_EMAIL: ${AUTH_BOOTSTRAP_ADMIN_EMAIL:-}
      AUTH_BOOTSTRAP_ADMIN_UNIT_ID: ${AUTH_BOOTSTRAP_ADMIN_UNIT_ID:-0}
      AUTH_BOOTSTRAP_ADMIN_UNIT_NAME: ${AUTH_BOOTSTRAP_ADMIN_UNIT_NAME:-Unidade Administrativa}
    command: mvn spring-boot:run -Dspring-boot.run.profiles=docker
    ports:
      - "${BACKEND_PORT}:8080"
    volumes:
      - ./src/backend:/workspace
      - maven_cache:/root/.m2
    depends_on:
      postgres:
        condition: service_healthy
      mailpit:
        condition: service_started
    networks:
      - estilo_marcado_network

  frontend:
    build:
      context: ./src/frontend
      dockerfile: Dockerfile.dev
    container_name: estilo-marcado-frontend
    # O volume de node_modules persiste entre rebuilds. Sincronize-o com o
    # package-lock atual antes de iniciar para evitar dependencias obsoletas.
    command: sh -c "npm install --no-audit --no-fund --prefer-offline && npm run start -- --host 0.0.0.0 --poll 1000"
    ports:
      - "${FRONTEND_PORT}:4200"
    volumes:
      - ./src/frontend:/workspace
      - frontend_node_modules:/workspace/node_modules
    depends_on:
      backend:
        condition: service_started
    networks:
      - estilo_marcado_network

  pgadmin:
    image: dpage/pgadmin4:latest
    container_name: estilo-marcado-pgadmin
    environment:
      PGADMIN_DEFAULT_EMAIL: ${PGADMIN_DEFAULT_EMAIL}
      PGADMIN_DEFAULT_PASSWORD: ${PGADMIN_DEFAULT_PASSWORD}
      PGADMIN_CONFIG_SERVER_MODE: "False"
    ports:
      - "${PGADMIN_PORT}:80"
    volumes:
      - pgadmin_data:/var/lib/pgadmin
    depends_on:
      postgres:
        condition: service_healthy
    networks:
      - estilo_marcado_network

  mailpit:
    image: axllent/mailpit:latest
    container_name: estilo-marcado-mailpit
    ports:
      - "${MAILPIT_SMTP_PORT}:1025"
      - "${MAILPIT_UI_PORT}:8025"
