import { ChangeDetectionStrategy, Component, inject, OnInit } from '@angular/core';
import { Router, RouterLink, RouterOutlet } from '@angular/router';
import { AuthService } from './auth.service';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [RouterLink, RouterOutlet],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <header><a class="brand" routerLink="/">Estilo <em>Marcado</em></a><nav>
      @if (auth.sessao(); as sessao) {
        <a routerLink="/conta">Minha conta</a>
        @if (sessao.perfil === 'ADMINISTRADOR') {
          <a routerLink="/administracao/usuarios">Equipe</a>
          <a routerLink="/administracao/estabelecimento">Estabelecimento</a>
        }
        <button class="link-button" (click)="sair()">Sair</button>
      } @else { <a routerLink="/entrar">Entrar</a><a class="nav-cta" routerLink="/cadastro">Criar conta</a> }
    </nav></header>
    <main><router-outlet /></main>
    <footer>Estilo Marcado · agendamentos com tranquilidade</footer>
  `
})
export class AppComponent implements OnInit {
  readonly auth = inject(AuthService); private readonly router = inject(Router);
  ngOnInit(): void { this.auth.carregarSessao().subscribe(); }
  sair(): void { this.auth.logout().subscribe(() => void this.router.navigateByUrl('/')); }
}
import { bootstrapApplication } from '@angular/platform-browser';
import { provideHttpClient, withInterceptors, withXsrfConfiguration } from '@angular/common/http';
import { provideRouter, Routes } from '@angular/router';
import { AppComponent } from './app/app.component';
import { administradorGuard, autenticadoGuard } from './app/auth.guard';
import { credentialsInterceptor } from './app/auth.service';
import { AtivacaoComponent, CadastroComponent, ContaComponent, HomeComponent, LoginComponent,
  NovaSenhaComponent, RecuperacaoComponent, UsuariosAdminComponent } from './app/auth-pages';
import { EstabelecimentoAdminComponent, FilialPublicaComponent } from './app/estabelecimento-pages';

const routes: Routes = [
  { path: '', component: HomeComponent },
  { path: 'entrar', component: LoginComponent },
  { path: 'cadastro', component: CadastroComponent },
  { path: 'ativar', component: AtivacaoComponent },
  { path: 'recuperar-conta', component: RecuperacaoComponent },
  { path: 'redefinir-senha', component: NovaSenhaComponent },
  { path: 'convite', component: NovaSenhaComponent, data: { convite: true } },
  { path: 'conta', component: ContaComponent, canActivate: [autenticadoGuard] },
  { path: 'administracao/usuarios', component: UsuariosAdminComponent, canActivate: [administradorGuard] },
  { path: 'administracao/estabelecimento', component: EstabelecimentoAdminComponent,
    canActivate: [administradorGuard] },
  { path: 'unidades/:id', component: FilialPublicaComponent },
  { path: '**', redirectTo: '' }
];

bootstrapApplication(AppComponent, {
  providers: [
    provideRouter(routes),
    provideHttpClient(
      withInterceptors([credentialsInterceptor]),
      withXsrfConfiguration({ cookieName: 'XSRF-TOKEN', headerName: 'X-XSRF-TOKEN' })
    )
  ]
}).catch((error: unknown) => console.error(error));
"}

