  criar(): void {
    const unidade = this.auth.sessao()?.unidadeId;
    if (unidade === null || unidade === undefined) { return; }
    this.auth.criarUsuario(unidade, { nome: this.nome, email: this.email, perfil: this.perfil, profissionalId: this.profissionalId })
