  }
  private carregar(): void {
    const unidade = this.auth.sessao()?.unidadeId;
    if (unidade !== null && unidade !== undefined) { this.auth.listarUsuarios(unidade).subscribe((u) => this.usuarios.set(u)); }
  }
}
