import { AuthService } from './auth.service';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [RouterLink, RouterOutlet],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <header><a class="brand" routerLink="/">Estilo <em>Marcado</em></a><nav>
      @if (auth.sessao(); as sessao) {
        <a routerLink="/conta">Minha conta</a>
        @if (sessao.perfil === 'ADMINISTRADOR') {
          <a routerLink="/administracao/usuarios">Equipe</a>
          <a routerLink="/administracao/estabelecimento">Estabelecimento</a>
        }
        <button class="link-button" (click)="sair()">Sair</button>
      } @else { <a routerLink="/entrar">Entrar</a><a class="nav-cta" routerLink="/cadastro">Criar conta</a> }
    </nav></header>
    <main><router-outlet /></main>
    <footer>Estilo Marcado · agendamentos com tranquilidade</footer>
  `
})
export class AppComponent implements OnInit {
  readonly auth = inject(AuthService); private readonly router = inject(Router);
  ngOnInit(): void { this.auth.carregarSessao().subscribe(); }
  sair(): void { this.auth.logout().subscribe(() => void this.router.navigateByUrl('/')); }
}
import { bootstrapApplication } from '@angular/platform-browser';
import { provideHttpClient, withInterceptors, withXsrfConfiguration } from '@angular/common/http';
import { provideRouter, Routes } from '@angular/router';
import { AppComponent } from './app/app.component';
import { administradorGuard, autenticadoGuard } from './app/auth.guard';
import { credentialsInterceptor } from './app/auth.service';
import { AtivacaoComponent, CadastroComponent, ContaComponent, HomeComponent, LoginComponent,
  NovaSenhaComponent, RecuperacaoComponent, UsuariosAdminComponent } from './app/auth-pages';
import { EstabelecimentoAdminComponent, FilialPublicaComponent } from './app/estabelecimento-pages';

const routes: Routes = [
  { path: '', component: HomeComponent },
  { path: 'entrar', component: LoginComponent },
  { path: 'cadastro', component: CadastroComponent },
  { path: 'ativar', component: AtivacaoComponent },
  { path: 'recuperar-conta', component: RecuperacaoComponent },
  { path: 'redefinir-senha', component: NovaSenhaComponent },
  { path: 'convite', component: NovaSenhaComponent, data: { convite: true } },
  { path: 'conta', component: ContaComponent, canActivate: [autenticadoGuard] },
  { path: 'administracao/usuarios', component: UsuariosAdminComponent, canActivate: [administradorGuard] },
  { path: 'administracao/estabelecimento', component: EstabelecimentoAdminComponent,
    canActivate: [administradorGuard] },
  { path: 'unidades/:id', component: FilialPublicaComponent },
  { path: '**', redirectTo: '' }
];

bootstrapApplication(AppComponent, {
  providers: [
    provideRouter(routes),
    provideHttpClient(
      withInterceptors([credentialsInterceptor]),
      withXsrfConfiguration({ cookieName: 'XSRF-TOKEN', headerName: 'X-XSRF-TOKEN' })
    )
  ]
}).catch((error: unknown) => console.error(error));
import { HttpClient, HttpErrorResponse, HttpInterceptorFn } from '@angular/common/http';
import { computed, inject, Injectable, signal } from '@angular/core';
import { catchError, map, Observable, of, switchMap, tap } from 'rxjs';

export type Perfil = 'CLIENTE' | 'PROFISSIONAL' | 'RECEPCAO' | 'ADMINISTRADOR';
export type Estado = 'PENDENTE' | 'ATIVA' | 'BLOQUEADA' | 'DESATIVADA';

export interface Sessao {
  id: number;
  nome: string;
  email: string;
  perfil: Perfil;
  unidadeId: number | null;
  profissionalId: number | null;
}

export interface Usuario extends Sessao {
  estado: Estado;
}

export interface ErroApi {
  mensagem?: string;
  campos?: Record<string, string>;
}

export const credentialsInterceptor: HttpInterceptorFn = (request, next) =>
  next(request.clone({ withCredentials: true }));

@Injectable({ providedIn: 'root' })
export class AuthService {
  private readonly http = inject(HttpClient);
  readonly sessao = signal<Sessao | null | undefined>(undefined);
  readonly autenticado = computed(() => this.sessao() !== null && this.sessao() !== undefined);
  readonly administrador = computed(() => this.sessao()?.perfil === 'ADMINISTRADOR');

  carregarSessao(): Observable<Sessao | null> {
    return this.http.get<Sessao>('/api/autenticacao/sessao').pipe(
      tap((sessao) => this.sessao.set(sessao)),
      map((sessao) => sessao as Sessao | null),
      catchError(() => {
        this.sessao.set(null);
        return of(null);
      })
    );
  }

  cadastrar(dados: { nome: string; email: string; senha: string; confirmacaoSenha: string }): Observable<unknown> {
    return this.mutacao(() => this.http.post('/api/autenticacao/cadastros', dados));
  }

  ativar(token: string): Observable<unknown> {
    return this.mutacao(() => this.http.post('/api/autenticacao/ativacoes', { token }));
  }

  login(email: string, senha: string): Observable<Sessao> {
    return this.mutacao(() => this.http.post<Sessao>('/api/autenticacao/sessoes', { email, senha })).pipe(
      tap((sessao) => this.sessao.set(sessao))
    );
  }

  logout(): Observable<unknown> {
    return this.mutacao(() => this.http.delete('/api/autenticacao/sessao')).pipe(
      tap(() => this.sessao.set(null))
    );
  }

  solicitarRecuperacao(email: string): Observable<unknown> {
    return this.mutacao(() => this.http.post('/api/autenticacao/recuperacoes', { email }));
  }

  redefinir(token: string, senha: string, confirmacaoSenha: string): Observable<unknown> {
    return this.mutacao(() =>
      this.http.post('/api/autenticacao/redefinicoes', { token, senha, confirmacaoSenha })
    );
  }

  aceitarConvite(token: string, senha: string, confirmacaoSenha: string): Observable<unknown> {
    return this.mutacao(() =>
      this.http.post('/api/autenticacao/convites', { token, senha, confirmacaoSenha })
    );
  }

  meuPerfil(): Observable<Usuario> {
    return this.http.get<Usuario>('/api/usuarios/me');
  }

  atualizarNome(nome: string): Observable<Usuario> {
    return this.mutacao(() => this.http.patch<Usuario>('/api/usuarios/me', { nome }));
  }

  listarUsuarios(unidadeId: number): Observable<Usuario[]> {
    return this.http.get<Usuario[]>(`/api/unidades/${unidadeId}/usuarios-internos`);
  }

  criarUsuario(unidadeId: number, dados: {
    nome: string;
    email: string;
    perfil: Perfil;
    profissionalId: number | null;
  }): Observable<Usuario> {
    return this.mutacao(() =>
      this.http.post<Usuario>(`/api/unidades/${unidadeId}/usuarios-internos`, dados)
    );
  }

  static mensagemErro(error: unknown): string {
    if (error instanceof HttpErrorResponse) {
      const body = error.error as ErroApi | undefined;
      return body?.mensagem ?? 'Nao foi possivel concluir a operacao.';
    }
    return 'Nao foi possivel concluir a operacao.';
  }

  private mutacao<T>(acao: () => Observable<T>): Observable<T> {
    return this.http.get('/api/autenticacao/csrf').pipe(switchMap(() => acao()));
  }
}
import { inject } from '@angular/core';
import { CanActivateFn, Router } from '@angular/router';
import { map, of } from 'rxjs';
import { AuthService } from './auth.service';

export const autenticadoGuard: CanActivateFn = () => {
  const auth = inject(AuthService);
  const router = inject(Router);
  const decidir = () => auth.sessao() ? true : router.createUrlTree(['/entrar']);
  return auth.sessao() === undefined ? auth.carregarSessao().pipe(map(decidir)) : of(decidir());
};

export const administradorGuard: CanActivateFn = () => {
  const auth = inject(AuthService);
  const router = inject(Router);
  const decidir = () => auth.sessao()?.perfil === 'ADMINISTRADOR'
    ? true
    : router.createUrlTree(['/']);
  return auth.sessao() === undefined ? auth.carregarSessao().pipe(map(decidir)) : of(decidir());
};
