input, select, textarea { width: 100%; border: 1px solid #d9cecb; border-radius: .75rem; padding: .85rem .95rem; background: #fdfcfc; color: var(--ink); outline: none; }
input:focus, select:focus, textarea:focus { border-color: var(--wine); box-shadow: 0 0 0 3px rgb(103 45 62 / 10%); }
textarea { min-height: 6rem; resize: vertical; }
.checkbox-line { display: flex; align-items: center; gap: .6rem; }
.checkbox-line input { width: auto; }
.content-card h2 { margin-top: 2rem; }
input:disabled { color: var(--muted); background: #f5f1ef; }
.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; }
.auth-links { display: flex; justify-content: space-between; margin-top: 1.2rem; font-size: .9rem; }
.notice { padding: .9rem 1rem; border-radius: .75rem; background: #f5f1ef; line-height: 1.5; }
.notice.error { color: #8f2435; background: #fff0f2; }
.notice.success { color: #295f42; background: #edf8f1; }
.badge { border-radius: 999px; background: var(--blush); color: var(--wine); font-size: .7rem; font-weight: 700; padding: .35rem .6rem; }
.inline-form { grid-template-columns: 1.2fr 1.4fr 1fr 1fr auto; align-items: end; padding: 1rem 0 1.5rem; border-bottom: 1px solid var(--line); }
.user-list { display: grid; }
.user-list article { display: grid; grid-template-columns: 1fr auto auto; align-items: center; gap: 1rem; padding: 1rem .25rem; border-bottom: 1px solid var(--line); }
.user-list small { display: block; color: var(--muted); margin-top: .25rem; }
.status { color: var(--muted); font-size: .75rem; }

@media (max-width: 760px) {
  header { min-height: 76px; height: auto; padding: .75rem 1rem; gap: .75rem; flex-wrap: wrap; }
  nav { gap: .75rem; flex-wrap: wrap; justify-content: flex-end; }
  main { padding: 2rem 1rem; }
  .hero { grid-template-columns: 1fr; gap: 2rem; margin-top: 0; }
  .hero-card { transform: none; }
  .form-grid, .inline-form { grid-template-columns: 1fr; }
  .user-list article { grid-template-columns: 1fr auto; }
  .user-list .status { grid-column: 2; }
}

