    this.auth.meuPerfil().subscribe({
      next: u => { this.usuario.set(u); this.nome = u.nome; this.telefone = u.telefoneContato ?? ''; },
      error: e => this.erro.set(AuthService.mensagemErro(e))
    });
  }
