@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,700;1,700&display=swap');

:root {
  color-scheme: light;
  font-family: 'DM Sans', sans-serif;
  color: #2d2627;
  background: #faf7f5;
  --wine: #672d3e;
  --wine-dark: #4b1d2b;
  --blush: #f1dcd8;
  --cream: #faf7f5;
  --ink: #2d2627;
  --muted: #766b6d;
  --line: #e8dedb;
}

* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; background: radial-gradient(circle at 90% 5%, #f5e7e3 0, transparent 28%), var(--cream); }
button, input, select, textarea { font: inherit; }
a { color: var(--wine); text-decoration: none; }

header {
  height: 76px; padding: 0 clamp(1.25rem, 6vw, 6rem); display: flex; align-items: center;
  justify-content: space-between; border-bottom: 1px solid var(--line); background: rgb(250 247 245 / 88%);
  backdrop-filter: blur(12px); position: sticky; top: 0; z-index: 10;
}
.brand { font: 700 1.45rem 'Playfair Display', serif; color: var(--ink); }
.brand em { color: var(--wine); }
nav { display: flex; align-items: center; gap: 1.4rem; font-size: .93rem; font-weight: 600; }
.nav-cta { color: white; background: var(--wine); padding: .65rem 1rem; border-radius: 999px; }
.link-button { border: 0; background: none; color: var(--wine); cursor: pointer; font-weight: 600; }
main { min-height: calc(100vh - 140px); padding: clamp(2rem, 6vw, 5rem) clamp(1rem, 6vw, 6rem); }
footer { text-align: center; color: var(--muted); padding: 1.5rem; font-size: .85rem; }

h1 { font: 700 clamp(2.2rem, 5vw, 4.8rem)/1.05 'Playfair Display', serif; margin: .35rem 0 1rem; letter-spacing: -.03em; }
.eyebrow { color: var(--wine); font-weight: 700; letter-spacing: .14em; text-transform: uppercase; font-size: .72rem; }
.lead { color: var(--muted); font-size: clamp(1rem, 2vw, 1.25rem); max-width: 36rem; line-height: 1.65; }
.hero { max-width: 1120px; margin: 4vh auto; display: grid; grid-template-columns: 1.35fr .65fr; gap: 5rem; align-items: center; }
.actions { display: flex; gap: .75rem; margin-top: 2rem; flex-wrap: wrap; }
.button { display: inline-flex; border: 1px solid var(--wine); border-radius: 999px; padding: .8rem 1.25rem; font-weight: 700; justify-content: center; cursor: pointer; }
.button.primary { background: var(--wine); color: white; box-shadow: 0 10px 24px rgb(103 45 62 / 20%); }
.button.primary:hover { background: var(--wine-dark); }
.button.ghost { background: transparent; color: var(--wine); }
.button:disabled { opacity: .55; cursor: not-allowed; }
.hero-card { padding: 2.2rem; border-radius: 1.5rem; background: var(--wine); color: white; box-shadow: 0 26px 60px rgb(75 29 43 / 24%); transform: rotate(2deg); }
.hero-card span, .hero-card small { display: block; opacity: .75; }
.hero-card strong { display: block; font: 700 2rem 'Playfair Display', serif; margin: 1.5rem 0 .4rem; }

.auth-card, .content-card { max-width: 520px; margin: 0 auto; padding: clamp(1.5rem, 4vw, 2.7rem); background: white; border: 1px solid var(--line); border-radius: 1.4rem; box-shadow: 0 20px 50px rgb(45 38 39 / 8%); }
.auth-card.wide, .content-card.wide { max-width: 880px; }
.auth-card h1, .content-card h1 { font-size: clamp(2rem, 4vw, 3.1rem); }
form { display: grid; gap: 1.15rem; margin: 1.5rem 0; }
label { display: grid; gap: .45rem; font-size: .85rem; font-weight: 700; color: #4a4143; }
input, select, textarea { width: 100%; border: 1px solid #d9cecb; border-radius: .75rem; padding: .85rem .95rem; background: #fdfcfc; color: var(--ink); outline: none; }
input:focus, select:focus, textarea:focus { border-color: var(--wine); box-shadow: 0 0 0 3px rgb(103 45 62 / 10%); }
textarea { min-height: 6rem; resize: vertical; }
.checkbox-line { display: flex; align-items: center; gap: .6rem; }
.checkbox-line input { width: auto; }
.content-card h2 { margin-top: 2rem; }
input:disabled { color: var(--muted); background: #f5f1ef; }
.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; }
