.welcome-art i { position: absolute; width: 230px; height: 230px; border: 1px solid rgb(103 45 62 / 17%); border-radius: 50%; right: -60px; top: -75px; }
.welcome-art i:last-child { width: 290px; height: 290px; right: -95px; top: -100px; }
.loading-state { color: var(--muted); padding: 3rem 0; }

.auth-card, .content-card { max-width: 570px; margin: 0 auto; padding: clamp(1.5rem, 4vw, 2.6rem); }
.auth-card.wide, .content-card.wide { max-width: 960px; }
.auth-card h1, .content-card h1 { font-size: clamp(2rem, 3.7vw, 3.1rem); }
form { display: grid; gap: 1.1rem; margin: 1.3rem 0 0; }
label { display: grid; gap: .48rem; color: #4a4143; font-size: .85rem; font-weight: 700; }
input, select, textarea { width: 100%; border: 1px solid #d9cecb; border-radius: .72rem; padding: .82rem .93rem; background: #fdfcfc; color: var(--ink); outline: none; }
input:focus, select:focus, textarea:focus { border-color: var(--wine); box-shadow: 0 0 0 3px rgb(103 45 62 / 11%); }
input:disabled { color: #645b5d; background: #f5f1ef; }
textarea { min-height: 6rem; resize: vertical; }
.checkbox-line { display: flex; align-items: center; gap: .6rem; }
.checkbox-line input { width: auto; }
.form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; }
.form-actions { display: flex; align-items: center; gap: .75rem; flex-wrap: wrap; margin-top: .55rem; }
.auth-links { display: flex; justify-content: space-between; gap: 1rem; flex-wrap: wrap; margin-top: 1.2rem; font-size: .9rem; }
.field-help { margin: -.7rem 0 0; color: var(--muted); font-size: .8rem; font-weight: 400; }
.field-error { margin: -.6rem 0 0; color: #8f2435; font-size: .8rem; }
.notice { padding: .9rem 1rem; border-radius: .75rem; background: var(--soft); line-height: 1.5; }
.notice.error { color: #8f2435; background: #fff0f2; }
.notice.success { color: #295f42; background: #edf8f1; }
.badge { display: inline-flex; align-items: center; width: fit-content; border-radius: 999px; background: var(--blush); color: var(--wine-dark); font-size: .75rem; font-weight: 700; padding: .35rem .7rem; }
.status { color: var(--muted); font-size: .8rem; }
.user-list { display: grid; margin-top: 1.1rem; }
.user-list article { display: flex; align-items: center; justify-content: space-between; gap: 1rem; flex-wrap: wrap; padding: 1rem .25rem; border-bottom: 1px solid var(--line); }
.user-list article:last-child { border-bottom: 0; }
.user-list article > div:first-child { flex: 1 1 200px; }
.user-list small { display: block; color: var(--muted); margin-top: .25rem; }
.inline-form { grid-template-columns: 1.2fr 1.4fr 1fr 1fr auto; align-items: end; border-bottom: 1px solid var(--line); padding-bottom: 1.4rem; }
.create-details { margin-top: 1.25rem; border-top: 1px solid var(--line); padding-top: 1.1rem; }
.create-details summary { display: flex; align-items: center; gap: .5rem; width: fit-content; color: var(--wine); font-weight: 700; padding: .5rem .75rem; border-radius: .65rem; }
.create-details summary:hover { background: var(--soft); color: var(--wine-dark); box-shadow: 0 6px 14px rgb(75 29 43 / 9%); }
.edit-panel { margin-top: 1.25rem; padding: 1.25rem; border-radius: 1rem; background: var(--soft); }
.edit-panel h3 { margin: 0; }

.profile-grid { display: grid; grid-template-columns: minmax(220px, 290px) minmax(0, 1fr); gap: 1.2rem; align-items: start; }
.profile-identity { text-align: center; }
.profile-avatar { width: 100px; height: 100px; margin: .4rem auto 1rem; }
.profile-avatar img { width: 100%; height: 100%; }
.profile-identity h2 { margin: .3rem 0 .7rem; font: 700 1.7rem 'Playfair Display', serif; overflow-wrap: anywhere; }
.profile-identity .badge { margin: 0 auto; }
.profile-identity p { color: var(--muted); font-size: .84rem; line-height: 1.5; margin-top: 1.2rem; }
.profile-details form { margin-top: 1.5rem; }
.affiliation-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; margin-top: 1.2rem; }
