.affiliation-grid span, .affiliation-grid small { color: var(--muted); font-size: .8rem; }
.affiliation-grid a { display: inline-flex; align-items: center; gap: .35rem; width: fit-content; font-weight: 700; }
.affiliation-grid a:hover { color: var(--wine-dark); text-decoration: underline; }
.affiliation-grid a .ui-icon { width: 16px; }

.agenda-panel { min-height: 300px; }
.agenda-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 1rem; flex-wrap: wrap; padding-bottom: 1.2rem; border-bottom: 1px solid var(--line); }
.agenda-toolbar h2 { margin: .2rem 0 0; font: 700 1.5rem 'Playfair Display', serif; text-transform: capitalize; }
.toolbar-label { color: var(--muted); font-size: .8rem; font-weight: 700; }
.toolbar-actions { display: flex; align-items: center; gap: .5rem; }
.icon-button { width: 44px; height: 44px; display: inline-grid; place-items: center; border: 1px solid var(--line); border-radius: .75rem; background: white; color: var(--wine); font-size: 1.5rem; transition: .18s ease; }
.icon-button:hover:not(:disabled) { color: var(--wine-dark); background: var(--soft); box-shadow: 0 8px 20px rgb(75 29 43 / 12%); }
.agenda-list { display: grid; }
.agenda-item { display: grid; grid-template-columns: 90px minmax(0, 1fr) auto; align-items: center; gap: 1.2rem; padding: 1.1rem .2rem; border-bottom: 1px solid var(--line); }
.agenda-item:last-child { border-bottom: 0; }
.agenda-item h3, .agenda-item p { margin: 0; }
.agenda-item p { color: var(--muted); font-size: .88rem; margin-top: .22rem; }
.agenda-time { display: flex; align-items: center; gap: .5rem; color: var(--wine); }
.agenda-time .ui-icon { width: 17px; }
.status-chip { border-radius: 999px; background: var(--soft); color: var(--wine-dark); padding: .4rem .7rem; font-size: .76rem; font-weight: 700; }
.agenda-item.is-cancelled { opacity: .64; }
.agenda-item.is-cancelled .status-chip { background: #f4e4e4; color: #8f2435; }
.empty-state { display: grid; justify-items: center; padding: 3rem 1rem; text-align: center; }
.empty-state h3 { margin: .3rem 0; }
.empty-state p { margin: 0; color: var(--muted); }

@media (max-width: 1000px) {
  .app-layout { grid-template-columns: 220px minmax(0, 1fr); }
  .app-sidebar { padding-inline: .6rem; }
  .profile-grid { grid-template-columns: 220px minmax(0, 1fr); }
}
@media (max-width: 760px) {
  .app-header { padding: 0 1rem; }
  .header-context { display: none; }
  .mobile-menu { display: inline-grid !important; }
  .app-layout { display: block; }
  .app-sidebar { position: fixed; top: 76px; bottom: 0; left: 0; z-index: 35; width: min(80vw, 290px); height: auto; transform: translateX(-105%); visibility: hidden; transition: transform .2s ease, visibility .2s ease; box-shadow: 14px 0 30px rgb(45 38 39 / 12%); }
  .app-sidebar.is-open { transform: translateX(0); visibility: visible; }
  .sidebar-scrim { display: block; position: fixed; inset: 76px 0 0; z-index: 30; border: 0; background: rgb(45 38 39 / 38%); width: 100%; }
  .app-main { padding: 1.5rem 1rem 3rem; }
  .hero, .dashboard-welcome { grid-template-columns: 1fr; gap: 2rem; margin-top: 0; }
  .hero-card, .welcome-art { min-height: 220px; height: 240px; }
  .profile-grid, .overview-grid { grid-template-columns: 1fr; }
  .profile-identity { display: grid; justify-items: center; }
  .form-grid, .affiliation-grid, .inline-form { grid-template-columns: 1fr; }
}
@media (max-width: 520px) {
  .account-name { display: none; }
  .avatar-trigger { gap: .15rem; }
  .public-nav { gap: .55rem; font-size: .82rem; }
  .public-nav .nav-cta { padding: .58rem .72rem; }
  .brand { font-size: 1.23rem; }
  .surface-panel { padding: 1.2rem; }
  .agenda-item { grid-template-columns: 1fr auto; gap: .55rem; }
  .agenda-time { grid-column: 1 / -1; }
  .agenda-toolbar h2 { font-size: 1.25rem; }
  .toolbar-actions { width: 100%; justify-content: space-between; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; animation-duration: .01ms !important; }
}

