package br.ufpa.dsai.estilomarcado.autenticacao.service;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import br.ufpa.dsai.estilomarcado.autenticacao.api.dto.AtualizarPerfilRequest;
import br.ufpa.dsai.estilomarcado.autenticacao.api.dto.MeuPerfilResponse;
import br.ufpa.dsai.estilomarcado.autenticacao.repository.UsuarioRepository;
import br.ufpa.dsai.estilomarcado.autenticacao.security.UsuarioAtual;
import br.ufpa.dsai.estilomarcado.catalogo.api.exception.RecursoNaoEncontradoException;

@Service
public class PerfilService {

    private final UsuarioRepository repository;
    private final UsuarioAtual usuarioAtual;

    public PerfilService(UsuarioRepository repository, UsuarioAtual usuarioAtual) {
        this.repository = repository;
        this.usuarioAtual = usuarioAtual;
    }

    @Transactional(readOnly = true)
    public MeuPerfilResponse consultar() {
        Long id = usuarioAtual.get().id();
        return repository.findById(id).map(MeuPerfilResponse::from)
                .orElseThrow(() -> new RecursoNaoEncontradoException("usuario nao encontrado"));
    }

    @Transactional
    public MeuPerfilResponse atualizar(AtualizarPerfilRequest request) {
        Long id = usuarioAtual.get().id();
        var usuario = repository.findById(id)
                .orElseThrow(() -> new RecursoNaoEncontradoException("usuario nao encontrado"));
        usuario.setNome(request.nome());
        if (request.telefoneInformado()) {
            usuario.setTelefoneContato(normalizarTelefone(request.telefoneContato()));
        }
        return MeuPerfilResponse.from(repository.save(usuario));
    }

    private String normalizarTelefone(String valor) {
        if (valor == null || valor.isBlank()) {
            return null;
        }
        String texto = valor.trim();
        if (!texto.matches("\\+?[0-9() .-]+")) {
            throw new IllegalArgumentException("telefoneContato invalido");
        }
        String digitos = texto.replaceAll("\\D", "");
        if (!texto.startsWith("+")) {
            if ((digitos.length() != 10 && digitos.length() != 11)
                    || digitos.charAt(0) == '0') {
                throw new IllegalArgumentException("telefoneContato deve incluir DDD");
            }
            digitos = "55" + digitos;
        }
        if (!digitos.matches("[1-9][0-9]{7,14}")) {
            throw new IllegalArgumentException("telefoneContato invalido");
        }
        return "+" + digitos;
    }
}
package br.ufpa.dsai.estilomarcado.painel.service;

import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.List;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.security.access.AccessDeniedException;

import br.ufpa.dsai.estilomarcado.agendamento.repository.AtendimentoRepository;
import br.ufpa.dsai.estilomarcado.autenticacao.model.PerfilUsuario;
import br.ufpa.dsai.estilomarcado.autenticacao.security.UsuarioAtual;
import br.ufpa.dsai.estilomarcado.catalogo.repository.ProfissionalRepository;
import br.ufpa.dsai.estilomarcado.painel.api.dto.AgendaAtendimentoResponse;
import br.ufpa.dsai.estilomarcado.painel.api.exception.PerfilNaoIdentificadoException;

@Service
public class PainelProfissionalService {

    private final AtendimentoRepository atendimentoRepository;
    private final ProfissionalRepository profissionalRepository;
    private final UsuarioAtual usuarioAtual;

    public PainelProfissionalService(AtendimentoRepository atendimentoRepository,
                                    ProfissionalRepository profissionalRepository,
                                    UsuarioAtual usuarioAtual) {
        this.atendimentoRepository = atendimentoRepository;
        this.profissionalRepository = profissionalRepository;
        this.usuarioAtual = usuarioAtual;
    }

    @Transactional(readOnly = true)
    public List<AgendaAtendimentoResponse> agendaAutenticada(LocalDate data) {
        var principal = usuarioAtual.get();
        if (principal.perfil() != PerfilUsuario.PROFISSIONAL || principal.profissionalId() == null
                || principal.unidadeId() == null) {
            throw new AccessDeniedException("acesso negado");
        }
        var profissional = profissionalRepository.findById(principal.profissionalId())
                .orElseThrow(() -> new AccessDeniedException("acesso negado"));
        if (!profissional.isAtivo() || !profissional.getUnidade().isAtiva()
                || !principal.unidadeId().equals(profissional.getUnidade().getId())) {
            throw new AccessDeniedException("acesso negado");
        }
        return agendaDoDia(profissional.getId(), data);
    }

    /**
     * Agenda de um dia do profissional identificado: somente os atendimentos
     * atribuidos a ele, ordenados por horario crescente.
     */
    @Transactional(readOnly = true)
    public List<AgendaAtendimentoResponse> agendaDoDia(Long profissionalId, LocalDate data) {
        if (profissionalId == null) {
            throw new PerfilNaoIdentificadoException("perfil profissional nao identificado");
        }

        LocalDateTime inicioDoDia = data.atStartOfDay();
        LocalDateTime inicioDoDiaSeguinte = data.plusDays(1).atStartOfDay();

        return atendimentoRepository
                .findByProfissionalIdAndInicioGreaterThanEqualAndInicioLessThanOrderByInicioAsc(
                        profissionalId, inicioDoDia, inicioDoDiaSeguinte)
                .stream()
                .map(AgendaAtendimentoResponse::from)
                .toList();
    }
}
package br.ufpa.dsai.estilomarcado.autenticacao.api.dto;

import java.util.Map;
import java.util.Set;

public record AtualizarPerfilRequest(String nome, String telefoneContato, boolean telefoneInformado) {
    private static final Set<String> CAMPOS_PERMITIDOS = Set.of("nome", "telefoneContato");

    public static AtualizarPerfilRequest from(Map<String, Object> campos) {
        if (!CAMPOS_PERMITIDOS.containsAll(campos.keySet())) {
            throw new IllegalArgumentException("campos de identidade ou vinculo nao podem ser alterados");
        }
        if (!(campos.get("nome") instanceof String nome)
                || nome.trim().length() < 2 || nome.trim().length() > 120) {
            throw new IllegalArgumentException("nome deve ter entre 2 e 120 caracteres");
        }
        Object telefone = campos.get("telefoneContato");
        if (telefone != null && !(telefone instanceof String)) {
            throw new IllegalArgumentException("telefoneContato deve ser texto ou null");
        }
        return new AtualizarPerfilRequest(nome.trim(), (String) telefone,
                campos.containsKey("telefoneContato"));
    }
}
package br.ufpa.dsai.estilomarcado.autenticacao.api.dto;

import br.ufpa.dsai.estilomarcado.autenticacao.model.EstadoConta;
import br.ufpa.dsai.estilomarcado.autenticacao.model.PerfilUsuario;
import br.ufpa.dsai.estilomarcado.autenticacao.model.Usuario;
import br.ufpa.dsai.estilomarcado.catalogo.model.Unidade;

public record MeuPerfilResponse(
        Long id, String nome, String email, PerfilUsuario perfil, EstadoConta estado,
        Long unidadeId, Long profissionalId, String telefoneContato,
        FilialResumo filial, EstabelecimentoResumo estabelecimento) {

    public static MeuPerfilResponse from(Usuario usuario) {
        Unidade unidade = usuario.getUnidade();
        return new MeuPerfilResponse(usuario.getId(), usuario.getNome(), usuario.getEmail(),
                usuario.getPerfil(), usuario.getEstado(),
                unidade == null ? null : unidade.getId(),
                usuario.getProfissional() == null ? null : usuario.getProfissional().getId(),
                usuario.getTelefoneContato(),
                unidade == null ? null : new FilialResumo(unidade.getId(), unidade.getNome(), unidade.isAtiva()),
                unidade == null ? null : new EstabelecimentoResumo(
                        unidade.getEstabelecimento().getId(), unidade.getEstabelecimento().getNome()));
    }

    public record FilialResumo(Long id, String nome, boolean ativa) {}
    public record EstabelecimentoResumo(Long id, String nome) {}
}

