.welcome-art i:last-child { width: 290px; height: 290px; right: -95px; top: -100px; }
.loading-state { color: var(--muted); padding: 3rem 0; }

.auth-card, .content-card { max-width: 570px; margin: 0 auto; padding: clamp(1.5rem, 4vw, 2.6rem); }
.auth-card.wide, .content-card.wide { max-width: 960px; }
.auth-card h1, .content-card h1 { font-size: clamp(2rem, 3.7vw, 3.1rem); }
form { display: grid; gap: 1.1rem; margin: 1.3rem 0 0; }
label { display: grid; gap: .48rem; color: #4a4143; font-size: .85rem; font-weight: 700; }
input, select, textarea { width: 100%; border: 1px solid #d9cecb; border-radius: .72rem; padding: .82rem .93rem; background: #fdfcfc; color: var(--ink); outline: none; }
input:focus, select:focus, textarea:focus { border-color: var(--wine); box-shadow: 0 0 0 3px rgb(103 45 62 / 11%); }
input:disabled { color: #645b5d; background: #f5f1ef; }
textarea { min-height: 6rem; resize: vertical; }
.checkbox-line { display: flex; align-items: center; gap: .6rem; }
.checkbox-line input { width: auto; }
.form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; }
.form-actions { display: flex; align-items: center; gap: .75rem; flex-wrap: wrap; margin-top: .55rem; }
.auth-links { display: flex; justify-content: space-between; gap: 1rem; flex-wrap: wrap; margin-top: 1.2rem; font-size: .9rem; }
.field-help { margin: -.7rem 0 0; color: var(--muted); font-size: .8rem; font-weight: 400; }
.field-error { margin: -.6rem 0 0; color: #8f2435; font-size: .8rem; }
